import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";

function Register() {
  const location = useLocation();

  const eventId   = location.state?.eventId   || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name:         "",
    college_name: "",
    phone:        "",
    email:        "",
    event_id:     eventId,
  });

  const [step,        setStep]        = useState(1); // 1=form, 2=payment, 3=waiting, 4=camera, 5=idcard
  const [userId,      setUserId]      = useState("");
  const [qrData,      setQrData]      = useState("");
  const [photo,       setPhoto]       = useState("");
  const [utrNumber,   setUtrNumber]   = useState("");
  const [utrError,    setUtrError]    = useState("");
  const [submitting,  setSubmitting]  = useState(false);
  const [polling,     setPolling]     = useState(false);
  const [pollStatus,  setPollStatus]  = useState("");

  const videoRef   = useRef(null);
  const canvasRef  = useRef(null);
  const idCardRef  = useRef(null);
  const streamRef  = useRef(null);
  const pollRef    = useRef(null);

  /* ── UPI Details ─────────────────────────── */
  const YOUR_UPI_ID = "arunsekar664@okaxis";
  const AMOUNT      = "1";
  const PAYEE_NAME  = "CollegeEvent";
  /* ─────────────────────────────────────────── */

  const upiQRValue = `upi://pay?pa=${YOUR_UPI_ID}&pn=${encodeURIComponent(PAYEE_NAME)}&am=${AMOUNT}&cu=INR`;

  /* =============================
     CLEANUP POLLING ON UNMOUNT
  ============================= */
  useEffect(() => {
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, []);

  /* =============================
     INPUT CHANGE
  ============================= */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* =============================
     UTR FORMAT VALIDATION
     - Min 10, max 22 chars
     - Alphanumeric only
     - Cannot be all same digits (e.g. 111111111111 = fake)
     - Cannot be sequential (123456789012 = fake)
  ============================= */
  const isValidUTRFormat = (utr) => {
    const t = utr.trim();

    // Length check
    if (t.length < 10 || t.length > 22) return { valid: false, reason: "UTR must be 10 to 22 characters long." };

    // Alphanumeric only
    if (!/^[a-zA-Z0-9]+$/.test(t)) return { valid: false, reason: "UTR must contain only letters and numbers. No spaces or special characters." };

    // Block all same characters (e.g. 000000000000, aaaaaaaaaaaa)
    if (/^(.)\1+$/.test(t)) return { valid: false, reason: "❌ This looks like a fake UTR. All characters are the same." };

    // Block obvious sequential numbers (123456789012, 012345678901)
    const sequential = "0123456789012345678901234567890";
    const reverseSeq = "9876543210987654321098765432109";
    if (sequential.includes(t) || reverseSeq.includes(t)) {
      return { valid: false, reason: "❌ This looks like a fake UTR. Sequential numbers are not valid." };
    }

    // Block common test/fake patterns
    const fakePatterns = [
      /^test/i, /^fake/i, /^dummy/i, /^sample/i,
      /^1234/, /^0000/, /^9999/,
    ];
    for (const pattern of fakePatterns) {
      if (pattern.test(t)) return { valid: false, reason: "❌ Invalid UTR detected. Please enter the actual UTR from your payment app." };
    }

    return { valid: true };
  };

  /* =============================
     STEP 1 → STEP 2 (Show Payment)
  ============================= */
  const handleShowPayment = (e) => {
    e.preventDefault();
    setStep(2);
    setUtrError("");
  };

  /* =============================
     SUBMIT UTR FOR ADMIN APPROVAL
     Flow: User submits UTR → saved as 'pending'
     → Admin checks bank & approves
     → Frontend polls every 5s
     → On approval → show camera & ID card
  ============================= */
  const submitUTR = async () => {
    setUtrError("");
    const trimmedUTR = utrNumber.trim();

    if (!trimmedUTR) {
      setUtrError("Please enter your UTR / Transaction ID.");
      return;
    }

    const validation = isValidUTRFormat(trimmedUTR);
    if (!validation.valid) {
      setUtrError(validation.reason);
      return;
    }

    setSubmitting(true);

    try {
      const res = await axios.post("http://localhost:5000/submit-utr", {
        utrNumber: trimmedUTR,
        amount:    AMOUNT,
        ...formData,
        photo,
      });

      if (res.data.success) {
        setUserId(res.data.userId);
        setQrData(res.data.qrData);
        setStep(3); // waiting for admin approval
        startPolling(res.data.userId);
      } else {
        setUtrError(res.data.message || "Submission failed. Please try again.");
      }
    } catch {
      setUtrError("Server error. Please make sure backend is running.");
    } finally {
      setSubmitting(false);
    }
  };

  /* =============================
     POLL PAYMENT STATUS
     Checks every 5 seconds if admin approved
  ============================= */
  const startPolling = (uid) => {
    setPolling(true);
    setPollStatus("⏳ Waiting for payment verification...");

    pollRef.current = setInterval(async () => {
      try {
        const res = await axios.get(`http://localhost:5000/user-status/${uid}`);
        if (res.data.success) {
          if (res.data.payment_status === "approved") {
            clearInterval(pollRef.current);
            setPolling(false);
            setPollStatus("✅ Payment Verified!");
            setStep(4); // go to camera step
          } else if (res.data.payment_status === "rejected") {
            clearInterval(pollRef.current);
            setPolling(false);
            setPollStatus("❌ Payment rejected. Please contact support.");
          } else {
            setPollStatus("⏳ Waiting for admin to verify your payment...");
          }
        }
      } catch {
        setPollStatus("⚠️ Checking status... please wait.");
      }
    }, 5000); // check every 5 seconds
  };

  /* =============================
     OPEN CAMERA
  ============================= */
  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      streamRef.current          = stream;
      videoRef.current.srcObject = stream;
      videoRef.current.play();
    } catch {
      alert("Camera access denied");
    }
  };

  /* =============================
     CAPTURE PHOTO
  ============================= */
  const capturePhoto = () => {
    const video  = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width  = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext("2d").drawImage(video, 0, 0);
    setPhoto(canvas.toDataURL("image/png"));
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
    }
    setStep(5); // show ID card
  };

  /* =============================
     DOWNLOAD ID CARD
  ============================= */
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link    = document.createElement("a");
      link.download = "Event_ID_Card.png";
      link.href     = canvas.toDataURL();
      link.click();
    });
  };

  /* =============================
     STYLES
  ============================= */
  const s = {
    page:       { minHeight: "100vh", backgroundColor: "#f3f4f6" },
    container:  { maxWidth: "480px", margin: "0 auto", padding: "24px 16px", textAlign: "center" },
    title:      { fontSize: "24px", fontWeight: "700", color: "#111827", marginBottom: "6px" },
    subtitle:   { fontSize: "14px", color: "#6b7280", marginBottom: "24px" },
    card:       { background: "#fff", borderRadius: "14px", padding: "24px", marginBottom: "16px", boxShadow: "0 1px 4px rgba(0,0,0,0.08)", textAlign: "left" },
    label:      { fontSize: "13px", fontWeight: "600", color: "#374151", marginBottom: "6px", display: "block" },
    hint:       { fontSize: "12px", color: "#9ca3af", marginBottom: "10px" },
    input:      { width: "100%", padding: "12px 14px", fontSize: "14px", borderRadius: "8px", border: "1px solid #d1d5db", marginBottom: "12px", boxSizing: "border-box", outline: "none", backgroundColor: "#fafafa" },
    primaryBtn: { width: "100%", padding: "14px", backgroundColor: "#4f46e5", color: "#fff", border: "none", borderRadius: "10px", fontSize: "15px", fontWeight: "700", cursor: "pointer", marginTop: "8px" },
    greenBtn:   { width: "100%", padding: "14px", backgroundColor: "#16a34a", color: "#fff", border: "none", borderRadius: "10px", fontSize: "15px", fontWeight: "700", cursor: "pointer", marginTop: "8px" },
    cyanBtn:    { width: "100%", padding: "14px", backgroundColor: "#0891b2", color: "#fff", border: "none", borderRadius: "10px", fontSize: "15px", fontWeight: "700", cursor: "pointer", marginTop: "12px" },
    disabledBtn:{ width: "100%", padding: "14px", backgroundColor: "#9ca3af", color: "#fff", border: "none", borderRadius: "10px", fontSize: "15px", fontWeight: "700", cursor: "not-allowed", marginTop: "4px" },
    errorBox:   { backgroundColor: "#fef2f2", border: "1px solid #fca5a5", borderRadius: "8px", padding: "10px 14px", marginBottom: "12px", fontSize: "13px", color: "#b91c1c", textAlign: "left" },
    infoBox:    { backgroundColor: "#eff6ff", border: "1px solid #bfdbfe", borderRadius: "8px", padding: "10px 14px", marginBottom: "16px", fontSize: "13px", color: "#1e40af", textAlign: "left" },
    warningBox: { backgroundColor: "#fefce8", border: "1px solid #fde047", borderRadius: "8px", padding: "10px 14px", marginBottom: "16px", fontSize: "13px", color: "#854d0e", textAlign: "left" },
    successBox: { backgroundColor: "#f0fdf4", border: "1px solid #86efac", borderRadius: "8px", padding: "12px 14px", marginBottom: "16px", fontSize: "13px", color: "#166534", textAlign: "left" },
    qrWrapper:  { display: "flex", flexDirection: "column", alignItems: "center", backgroundColor: "#f9fafb", border: "1px solid #e5e7eb", borderRadius: "12px", padding: "20px", marginBottom: "16px" },
    backBtn:    { background: "none", border: "none", color: "#6b7280", cursor: "pointer", textDecoration: "underline", fontSize: "13px", marginTop: "12px", display: "block", width: "100%", textAlign: "center" },
    idCard:     { border: "2px solid #4f46e5", width: "300px", margin: "auto", padding: "20px", borderRadius: "14px", backgroundColor: "#fff", boxShadow: "0 4px 12px rgba(79,70,229,0.15)" },
    stepBadge:  (active) => ({ display: "inline-block", width: 28, height: 28, borderRadius: "50%", backgroundColor: active ? "#4f46e5" : "#e5e7eb", color: active ? "#fff" : "#6b7280", fontSize: 13, fontWeight: 700, lineHeight: "28px", textAlign: "center", margin: "0 4px" }),
  };

  return (
    <div style={s.page}>
      <Navbar />
      <div style={s.container}>
        <h2 style={s.title}>Event Registration</h2>
        <p style={s.subtitle}>Fill the form and pay ₹{AMOUNT} to register</p>

        {/* Step Indicator */}
        <div style={{ marginBottom: 20 }}>
          {["Form", "Pay", "Verify", "Photo", "ID Card"].map((label, i) => (
            <span key={i}>
              <span style={s.stepBadge(step === i + 1)}>{i + 1}</span>
              <span style={{ fontSize: 11, color: step === i + 1 ? "#4f46e5" : "#9ca3af" }}>{label}</span>
              {i < 4 && <span style={{ color: "#d1d5db", margin: "0 4px" }}>›</span>}
            </span>
          ))}
        </div>

        {/* ══════════════════════════
            STEP 1 — FORM
        ══════════════════════════ */}
        {step === 1 && (
          <form onSubmit={handleShowPayment}>
            <div style={s.card}>
              <label style={s.label}>Full Name</label>
              <input style={s.input} name="name" placeholder="Enter your name" onChange={handleChange} required />

              <label style={s.label}>College Name</label>
              <input style={s.input} name="college_name" placeholder="Enter college name" onChange={handleChange} required />

              <label style={s.label}>Phone Number</label>
              <input style={s.input} name="phone" placeholder="Enter phone number" type="tel" onChange={handleChange} required />

              <label style={s.label}>Email Address</label>
              <input style={s.input} name="email" placeholder="Enter email address" type="email" onChange={handleChange} required />

              <div style={s.successBox}>
                Selected Event: <strong>{eventName}</strong>
              </div>

              <button type="submit" style={s.primaryBtn}>
                Proceed to Pay ₹{AMOUNT}
              </button>
            </div>
          </form>
        )}

        {/* ══════════════════════════
            STEP 2 — PAYMENT + UTR
        ══════════════════════════ */}
        {step === 2 && (
          <div>
            {/* QR Card */}
            <div style={s.card}>
              <label style={{ ...s.label, fontSize: 15 }}>Scan QR &amp; Pay ₹{AMOUNT}</label>
              <p style={s.hint}>Open GPay / PhonePe / Paytm → Scan QR → Pay</p>

              <div style={s.qrWrapper}>
                <div style={{ padding: 12, backgroundColor: "#fff", borderRadius: 10, border: "1px solid #e5e7eb" }}>
                  <QRCode value={upiQRValue} size={180} />
                </div>
                <p style={{ marginTop: 12, fontSize: 12, color: "#6b7280" }}>
                  UPI ID: <strong style={{ color: "#111827" }}>{YOUR_UPI_ID}</strong>
                </p>
                <p style={{ fontSize: 12, color: "#6b7280", marginTop: 4 }}>
                  Amount: <strong style={{ color: "#111827" }}>₹{AMOUNT}</strong>
                </p>
              </div>

              <div style={s.infoBox}>
                <strong>How to pay:</strong><br />
                1. Open GPay / PhonePe / Paytm<br />
                2. Tap <strong>Scan QR</strong> and scan above<br />
                3. Confirm payment of ₹{AMOUNT}<br />
                4. Copy the <strong>UTR / Transaction ID</strong> from the app
              </div>
            </div>

            {/* UTR Card */}
            <div style={s.card}>
              <label style={s.label}>Enter UTR / Transaction ID</label>
              <p style={s.hint}>
                GPay → UPI Ref. No. &nbsp;|&nbsp;
                PhonePe → Transaction ID &nbsp;|&nbsp;
                Paytm → UTR Number &nbsp;|&nbsp;
                Or check bank SMS
              </p>

              <div style={s.warningBox}>
                ⚠️ <strong>Important:</strong> Enter only the real UTR from your payment app.
                Fake UTRs will be detected and your registration will be <strong>rejected</strong>.
                Admin will verify your payment before generating the ID card.
              </div>

              {utrError && <div style={s.errorBox}>⚠️ {utrError}</div>}

              <input
                type="text"
                placeholder="Enter UTR / Transaction ID"
                value={utrNumber}
                onChange={(e) => {
                  setUtrError("");
                  setUtrNumber(e.target.value.replace(/\s/g, "").slice(0, 22));
                }}
                style={{
                  ...s.input,
                  border:        utrError ? "1px solid #f87171" : "1px solid #d1d5db",
                  letterSpacing: "1px",
                  marginBottom:  "8px",
                }}
              />

              {submitting || utrNumber.trim().length < 10 ? (
                <button disabled style={s.disabledBtn}>
                  {submitting ? "Submitting..." : "Submit UTR for Verification"}
                </button>
              ) : (
                <button onClick={submitUTR} style={s.greenBtn}>
                  Submit UTR for Verification
                </button>
              )}
            </div>

            <button
              onClick={() => { setStep(1); setUtrNumber(""); setUtrError(""); }}
              style={s.backBtn}
            >
              ← Back to Form
            </button>
          </div>
        )}

        {/* ══════════════════════════
            STEP 3 — WAITING FOR ADMIN
        ══════════════════════════ */}
        {step === 3 && (
          <div style={s.card}>
            <div style={{ textAlign: "center", padding: "20px 0" }}>

              {/* Spinner */}
              {polling && (
                <div style={{
                  width:  48, height: 48,
                  border: "4px solid #e5e7eb",
                  borderTop: "4px solid #4f46e5",
                  borderRadius: "50%",
                  animation: "spin 1s linear infinite",
                  margin: "0 auto 16px",
                }} />
              )}

              <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>

              <h3 style={{ color: "#4f46e5", marginBottom: 8 }}>
                UTR Submitted Successfully!
              </h3>

              <p style={{ color: "#6b7280", fontSize: 14, marginBottom: 16 }}>
                Your UTR <strong style={{ color: "#111827" }}>{utrNumber}</strong> has been submitted.
                Admin is verifying your payment.
              </p>

              <div style={{
                ...s.infoBox,
                textAlign: "center",
                fontSize: 13,
              }}>
                {pollStatus}
              </div>

              <div style={{ ...s.warningBox, textAlign: "left" }}>
                <strong>What happens next?</strong><br />
                1. Admin checks your UTR in their bank app<br />
                2. If payment is genuine → <strong>Approved ✅</strong><br />
                3. If UTR is fake → <strong>Rejected ❌</strong><br />
                4. This page auto-updates every 5 seconds
              </div>

              <p style={{ fontSize: 12, color: "#9ca3af", marginTop: 8 }}>
                Do not close this page. Your ID card will appear here once approved.
              </p>
            </div>
          </div>
        )}

        {/* ══════════════════════════
            STEP 4 — CAMERA (after approval)
        ══════════════════════════ */}
        {step === 4 && (
          <div style={s.card}>
            <div style={s.successBox}>
              ✅ Payment verified! Take your photo to generate ID card.
            </div>

            <p style={{ ...s.label, fontSize: 15 }}>Your Registration QR Code</p>
            <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}>
              <QRCode value={qrData.toString()} size={180} />
            </div>

            <button onClick={openCamera} style={s.primaryBtn}>
              Open Camera for Photo
            </button>

            <video
              ref={videoRef}
              width="100%"
              style={{ borderRadius: 8, border: "1px solid #e5e7eb", display: "block", marginTop: 12 }}
            />

            <button onClick={capturePhoto} style={s.cyanBtn}>
              Capture Photo
            </button>

            <canvas ref={canvasRef} style={{ display: "none" }} />
          </div>
        )}

        {/* ══════════════════════════
            STEP 5 — ID CARD
        ══════════════════════════ */}
        {step === 5 && (
          <div style={{ marginTop: 10 }}>
            <p style={{ ...s.label, fontSize: 15, textAlign: "center" }}>
              Your Event ID Card
            </p>

            <div ref={idCardRef} style={s.idCard}>
              <h3 style={{ color: "#4f46e5", marginBottom: 12, fontSize: 16 }}>
                College Event ID Card
              </h3>
              <p style={{ fontSize: 14, marginBottom: 6 }}>
                <strong>Name:</strong> {formData.name}
              </p>
              <p style={{ fontSize: 14, marginBottom: 6 }}>
                <strong>User ID:</strong> {userId}
              </p>
              <p style={{ fontSize: 14, marginBottom: 14 }}>
                <strong>Event:</strong> {eventName}
              </p>
              <div style={{ display: "flex", justifyContent: "center", marginBottom: 14 }}>
                <QRCode value={qrData.toString()} size={120} />
              </div>
              <div style={{ display: "flex", justifyContent: "center" }}>
                <img
                  src={photo}
                  alt="User"
                  width="110"
                  style={{ borderRadius: 8, border: "2px solid #e5e7eb" }}
                />
              </div>
            </div>

            <button onClick={downloadCard} style={{ ...s.greenBtn, marginTop: 16 }}>
              Download ID Card
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Register;
